/// Retrieve the full list of extra classic visual appearance schemes and their binary payloads.
pub fn get_extra_classic_schemes() -> &'static [(&'static str, &'static [u8])] {
    &[
        ("Brick", SCHEME_BRICK),
        ("Desert", SCHEME_DESERT),
        ("Eggplant", SCHEME_EGGPLANT),
        ("High Contrast #1", SCHEME_HIGH_CONTRAST_1),
        (
            "High Contrast #1 (extra large)",
            SCHEME_HIGH_CONTRAST_1_EXTRA_LARGE,
        ),
        ("High Contrast #1 (large)", SCHEME_HIGH_CONTRAST_1_LARGE),
        ("High Contrast #2", SCHEME_HIGH_CONTRAST_2),
        (
            "High Contrast #2 (extra large)",
            SCHEME_HIGH_CONTRAST_2_EXTRA_LARGE,
        ),
        ("High Contrast #2 (large)", SCHEME_HIGH_CONTRAST_2_LARGE),
        ("High Contrast Black", SCHEME_HIGH_CONTRAST_BLACK),
        (
            "High Contrast Black (extra large)",
            SCHEME_HIGH_CONTRAST_BLACK_EXTRA_LARGE,
        ),
        (
            "High Contrast Black (large)",
            SCHEME_HIGH_CONTRAST_BLACK_LARGE,
        ),
        ("High Contrast White", SCHEME_HIGH_CONTRAST_WHITE),
        (
            "High Contrast White (extra large)",
            SCHEME_HIGH_CONTRAST_WHITE_EXTRA_LARGE,
        ),
        (
            "High Contrast White (large)",
            SCHEME_HIGH_CONTRAST_WHITE_LARGE,
        ),
        ("Lilac", SCHEME_LILAC),
        ("Lilac (large)", SCHEME_LILAC_LARGE),
        ("Maple", SCHEME_MAPLE),
        ("Marine (high color)", SCHEME_MARINE_HIGH_COLOR),
        ("Plum (high color)", SCHEME_PLUM_HIGH_COLOR),
        ("Pumpkin (large)", SCHEME_PUMPKIN_LARGE),
        ("Rainy Day", SCHEME_RAINY_DAY),
        ("Red, White, and Blue (VGA)", SCHEME_RED_WHITE_AND_BLUE_VGA),
        ("Rose", SCHEME_ROSE),
        ("Rose (large)", SCHEME_ROSE_LARGE),
        ("Slate", SCHEME_SLATE),
        ("Spruce", SCHEME_SPRUCE),
        ("Storm (VGA)", SCHEME_STORM_VGA),
        ("Teal (VGA)", SCHEME_TEAL_VGA),
        ("Wheat", SCHEME_WHEAT),
        ("Windows Classic", SCHEME_WINDOWS_CLASSIC),
        (
            "Windows Classic (extra large)",
            SCHEME_WINDOWS_CLASSIC_EXTRA_LARGE,
        ),
        ("Windows Classic (large)", SCHEME_WINDOWS_CLASSIC_LARGE),
        ("Windows Standard", SCHEME_WINDOWS_STANDARD),
        (
            "Windows Standard (extra large)",
            SCHEME_WINDOWS_STANDARD_EXTRA_LARGE,
        ),
        ("Windows Standard (large)", SCHEME_WINDOWS_STANDARD_LARGE),
    ]
}
